function getByModule(moduleName) {
  return TEACH_MODE_BUGS.filter((b) => b.module === moduleName);
}

function getUnmatched() {
  return TEACH_MODE_BUGS.filter((b) => !b.matchedTestId);
}

const OPEN_STATUSES = ['To do', 'Reopened', 'Ready for Testing', 'On Hold'];

function getOpen() {
  return TEACH_MODE_BUGS.filter((b) => OPEN_STATUSES.includes(b.status));
}

// Full repro text (Description/Expected Result/Actual Result, as one field) isn't copied into
// TEACH_MODE_BUGS/EXCLUDED_PLAN_MODE_BUGS above -- for 620+73 bugs that would make this file huge
// for data only needed while writing a test. Read it on demand from the source workbook instead.
let _descriptionCache = null;

function getDescription(itemId) {
  if (!_descriptionCache) {
    const xlsx = require('xlsx');
    const path = require('path');
    const wb = xlsx.readFile(path.join(__dirname, '..', 'CEP_TestCases', 'Zoho_Bugs_TeachMode.xlsx'));
    _descriptionCache = new Map();
    for (const sheetName of ['Teach Mode Bugs', 'Excluded - Plan Mode']) {
      const rows = xlsx.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' });
      for (const r of rows) _descriptionCache.set(r['Item Id'], r.Description);
    }
  }
  return _descriptionCache.get(itemId);
}

module.exports = {
  TEACH_MODE_BUGS,
  EXCLUDED_PLAN_MODE_BUGS,
  OPEN_STATUSES,
  getByModule,
  getUnmatched,
  getOpen,
  getDescription,
};
